import json
import re


class KeywordMapper:
    """Class useful to get keyword mapping statistics in a given admin interface(facade)."""

    implement_pattern = 'cli-docs/tutorial-(.*?).html'
    wrap_pattern = 'Wraps \'(.*?)\' keyword'

    def __init__(self, class_):
        self._class_ = class_
        self._map_keywords()
        self.all_keywords = self.mapped_keywords.keys()
        self.implementations = {k: v for (k, v) in self.mapped_keywords.items() if 'wraps' not in v}
        self.implementing_keywords = self.implementations.keys()
        self.cli_procedures = self.implementations.values()
        self.wrappers = {k: v for (k, v) in self.mapped_keywords.items() if 'wraps' in v}
        self.wrapping_keywords = self.wrappers.keys()

    def _map_keywords(self):
        """Maps keywords according to their role (implementation/wrapping)."""
        namespaces = [namespace for namespace in dir(self._class_) if not namespace.startswith('_')]
        self.mapped_keywords = {}
        for namespace in namespaces:
            docstring = getattr(self._class_, namespace).__doc__
            if docstring:
                if re.search(self.implement_pattern, docstring):
                    self.mapped_keywords.update(
                        {namespace: re.search(self.implement_pattern, docstring).group(1)})
                elif re.search(self.wrap_pattern, docstring):
                    self.mapped_keywords.update(
                        {namespace: 'wraps {}'.format(re.search(self.wrap_pattern, docstring).group(1))})

    def save_mapping_metric(self, metric_name, output_filename):
        """Saves given metric to a json file. Must be a dictionary."""
        metric = getattr(self, metric_name)
        if isinstance(metric, dict):
            with open(output_filename, 'w') as json_file:
                json_file.write(json.dumps(metric, separators=(',', ':')))
        else:
            raise Exception('Given object is not a dict, cannot be saved as a json file.')
